package breadcrumb

props {
  Class    string   = ""
  Children gx.Node  = nil
  Attrs    gx.Attrs = nil
}

<li role="presentation" aria-hidden="true" class={gx.Cx("[&>svg]:size-3.5", p.Class)} {...p.Attrs}>
  if p.Children != nil {
    {p.Children}
  } else {
    <span>/</span>
  }
</li>

